import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def sequence_x(n, k):
    """Calculates x_k = lcm(k, k+1, ..., k+n-1)"""
    if n <= 0:
        return 1

    numbers = range(k, k + n)

    # Calculate LCM of all numbers in the range
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = lcm(result, numbers[i])
    return result

# Test cases: n=1 to 5, k=1 to 15 (to check k > 10)
N_values = [1, 2, 3, 4, 5]
K_values = range(1, 16)

results = {}

for n in N_values:
    results[n] = {}
    print(f"--- Testing n = {n} ---")

    # Check the condition x_{k+1} > x_k
    is_weakly_increasing = True

    for k in K_values:
        x_k = sequence_x(n, k)
        x_k_plus_1 = sequence_x(n, k + 1)

        comparison = ""
        if x_k_plus_1 > x_k:
            comparison = ">"
        elif x_k_plus_1 == x_k:
            comparison = "="
        else: # x_{k+1} < x_k (should be rare/impossible for positive sequence elements)
            comparison = "<"
            is_weakly_increasing = False

        results[n][k] = (x_k, x_k_plus_1, comparison)

        if k > 10:
            print(f"k={k}: x_k = {x_k} (length: {len(str(x_k))}), x_{k+1} = {x_k_plus_1} (length: {len(str(x_k_plus_1))}) -> {comparison}")

    if is_weakly_increasing:
        print(f"Pattern observation for n={n}: x_{k+1} >= x_k for all tested k.")
    else:
        print(f"Pattern observation for n={n}: Found k where x_{k+1} < x_k.")

# Print the structure of results for easy analysis later
print("\n--- Summary of results (k=1 to 10) ---")
for n in N_values:
    print(f"\nN={n}:")
    for k in range(1, 11):
        x_k, x_k_plus_1, comp = results[n][k]
        print(f"  k={k}: x_k={x_k}, x_{k+1}={x_k_plus_1} ({comp})")

