import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

n = 3
k_values = range(1, 101)
results = []

for k in k_values:
    x_k = list_lcm(range(k, k + n))
    x_k_plus_1 = list_lcm(range(k + 1, k + 1 + n))

    comparison = ""
    if x_k_plus_1 > x_k:
        comparison = "Increase"
    elif x_k_plus_1 < x_k:
        comparison = "Decrease"
    else:
        comparison = "Plateau"

    results.append((k, x_k, x_k_plus_1, comparison))

# Print only the results where x_{k+1} <= x_k (Decreases or Plateaus)
decreases = [r for r in results if r[3] != "Increase"]

print("--- Decreases/Plateaus for n=3 (k=1 to 100) ---")
for k, x_k, x_k_plus_1, comparison in decreases:
    print(f"k={k}: x_k={x_k}, x_{k+1}={x_k_plus_1}, Comparison: {comparison}")

# Check the ratio for a few large k values
large_k_ratios = []
for k in range(50, 101):
    x_k = list_lcm(range(k, k + n))
    x_k_plus_1 = list_lcm(range(k + 1, k + 1 + n))
    ratio = x_k_plus_1 / x_k
    large_k_ratios.append(ratio)

print("\n--- Ratios x_{k+1}/x_k for k=50 to 100 ---")
# Print a subset of ratios
for i, ratio in enumerate(large_k_ratios):
    if i % 10 == 0:
        print(f"k={50+i}: Ratio = {ratio:.4f}")
